+++ b/src/utils/uvAdvice.js
@@ -0,0 +1,11 @@
+/**
+ * 根据紫外线指数给出强度等级；非法输入返回 null。
+ * 0-2 弱，3-5 中等，6-7 强，8 及以上极强。
+ */
+export function uvAdvice(uv) {
+  if (typeof uv !== "number" || !Number.isFinite(uv) || uv < 0) return null;
+  if (uv < 3) return "弱";
+  if (uv < 6) return "中等";
+  if (uv < 8) return "强";
+  return "极强";
+}
