+const PROTECTION_ADVICE = {
+  弱: "无需特别防护",
+  中等: "建议涂抹防晒霜",
+  强: "外出请做好防护",
+  极强: "务必做好防护",
+};
+
+/** 返回带防护建议的紫外线强度文案；非法输入返回 null。 */
+export function uvAdviceLabel(uv) {
+  const level = uvAdvice(uv);
+  return level ? `${level} · ${PROTECTION_ADVICE[level]}` : null;
+}
